l_show_admin_panel_md = {
    "ru": "<b>👩🏽‍💻 Создание и редактирование блога</b>\n\n👩🏽‍💻 Выполнен вход в режиме <b>Администратор</b>: можно создавать и редактировать блоги, но не удалять их\n\n<blockquote>¹ Авторизация (в течение 10сек) по ссылке в браузере:\n<code>{0}</code>\n\n² Перейди (в течение 10сек) по нужной ссылке для редактирования публикации (жми, чтобы скопировать):</blockquote>\n\n",
    "en": "<b>👩🏽‍💻 Creating and editing a blog</b>\n\n👩🏽‍💻 Logged in as <b>Administrator</b>: you can create and edit blogs, but not delete them\n\n<blockquote>¹ Authorization (within 10 seconds) via the link in the browser:\n<code>{0}</code>\n\n² Go (within 10 seconds) to the necessary link to edit the post (click to copy):</blockquote>",
    "es": "<b>👩🏽‍💻 Creación y edición de blogs</b>\n\n👩🏽‍💻 Has iniciado sesión como <b>Administrador</b>: puedes crear y editar blogs, pero no eliminarlos\n\n<blockquote>¹ Autorización (dentro de 10 segundos) a través del enlace en el navegador:\n<code>{0}</code>\n\n² Ve (dentro de 10 segundos) al enlace necesario para editar la publicación (haz clic para copiar):</blockquote>",
    "fr": "<b>👩🏽‍💻 Création et édition de blog</b>\n\n👩🏽‍💻 Connexion en mode <b>Administrateur</b> : vous pouvez créer et éditer des blogs, mais pas les supprimer\n\n<blockquote>¹ Authentification (dans les 10 secondes) via le lien dans le navigateur :\n<code>{0}</code>\n\n² Allez (dans les 10 secondes) sur le lien nécessaire pour éditer la publication (cliquez pour copier) :</blockquote>",
    "zh": "<b>👩🏽‍💻 创建和编辑博客</b>\n\n👩🏽‍💻 已以 <b>管理员</b> 身份登录：可以创建和编辑博客，但不能删除它们\n\n<blockquote>¹ 在浏览器中通过链接进行授权（在10秒内）：\n<code>{0}</code>\n\n² 在10秒内点击所需链接以编辑发布（点击以复制）：</blockquote>",
    "ar": "<b>👩🏽‍💻 إنشاء وتحرير المدونة</b>\n\n👩🏽‍💻 تم تسجيل الدخول كـ <b>مدير</b>: يمكنك إنشاء وتحرير المدونات، ولكن لا يمكنك حذفها\n\n<blockquote>¹ تسجيل الدخول (خلال 10 ثواني) عبر الرابط في المتصفح:\n<code>{0}</code>\n\n² انتقل (خلال 10 ثواني) إلى الرابط المطلوب لتحرير المنشور (اضغط لنسخ):</blockquote>",
}
