l_grp_no_original_group_id = {
    "ru": "🫧 <b>Все классно</b>! Но не удается найти идентификатор группы. Возможные решения:\n\n<blockquote><tg-emoji emoji-id='5408851018219790524'>▪️</tg-emoji> проверить наличие @FereyGroupBot в группе с правами [Администратор]\n<tg-emoji emoji-id='5408851018219790524'>▪️</tg-emoji> в пересылаемые сообщения добавить хотя бы одно ‘свежее’ сообщение с текстом (потом его можно будет удалить)\n<tg-emoji emoji-id='5408851018219790524'>▪️</tg-emoji> для создания любых NFT-далогов без группы (в том числе приватных) можно сделать пересылку в @FereyTONestBot</blockquote>",
    "en": "🫧 <b>Everything is great</b>! But unable to find the group identifier. Possible solutions:\n\n<blockquote><tg-emoji emoji-id='5408851018219790524'>▪️</tg-emoji> check for the presence of @FereyGroupBot in the group with [Administrator] rights\n<tg-emoji emoji-id='5408851018219790524'>▪️</tg-emoji> add at least one 'fresh' message with text to the forwarded messages (it can be deleted later)\n<tg-emoji emoji-id='5408851018219790524'>▪️</tg-emoji> to create any NFT dialogues without a group (including private ones), you can forward to @FereyTONestBot</blockquote>",
    "es": "🫧 <b>¡Todo está genial!</b> Pero no se puede encontrar el identificador del grupo. Posibles soluciones:\n\n<blockquote><tg-emoji emoji-id='5408851018219790524'>▪️</tg-emoji> verificar la presencia de @FereyGroupBot en el grupo con derechos [Administrador]\n<tg-emoji emoji-id='5408851018219790524'>▪️</tg-emoji> agregar al menos un mensaje 'nuevo' con texto a los mensajes reenviados (luego se puede eliminar)\n<tg-emoji emoji-id='5408851018219790524'>▪️</tg-emoji> para crear cualquier diálogo NFT sin grupo (incluidos los privados) se puede reenviar a @FereyTONestBot</blockquote>",
    "fr": "🫧 <b>Tout est génial</b> ! Mais je ne parviens pas à trouver l'identifiant du groupe. Solutions possibles :\n\n<blockquote><tg-emoji emoji-id='5408851018219790524'>▪️</tg-emoji> vérifier la présence de @FereyGroupBot dans le groupe avec des droits [Administrateur]\n<tg-emoji emoji-id='5408851018219790524'>▪️</tg-emoji> ajouter au moins un message ‘frais’ avec du texte dans les messages transférés (vous pourrez ensuite le supprimer)\n<tg-emoji emoji-id='5408851018219790524'>▪️</tg-emoji> pour créer n'importe quel dialogue NFT sans groupe (y compris privés), vous pouvez transférer vers @FereyTONestBot</blockquote>",
    "zh": "🫧 <b>一切都很好</b>！但无法找到组的标识符。可能的解决方案：\n\n<blockquote><tg-emoji emoji-id='5408851018219790524'>▪️</tg-emoji> 检查群组中是否存在 @FereyGroupBot，且具有 [管理员] 权限\n<tg-emoji emoji-id='5408851018219790524'>▪️</tg-emoji> 在转发的消息中添加至少一条“新鲜”的文本消息（之后可以删除）\n<tg-emoji emoji-id='5408851018219790524'>▪️</tg-emoji> 要创建任何没有群组的 NFT 对话（包括私密的），可以转发到 @FereyTONestBot</blockquote>",
    "ar": "🫧 <b>كل شيء رائع</b>! لكن لا يمكن العثور على معرف المجموعة. الحلول الممكنة:\n\n<blockquote><tg-emoji emoji-id='5408851018219790524'>▪️</tg-emoji> تحقق من وجود @FereyGroupBot في المجموعة مع حقوق [مدير]\n<tg-emoji emoji-id='5408851018219790524'>▪️</tg-emoji> أضف على الأقل رسالة واحدة 'جديدة' إلى الرسائل المعاد توجيهها (يمكنك حذفها لاحقًا)\n<tg-emoji emoji-id='5408851018219790524'>▪️</tg-emoji> لإنشاء أي محادثات NFT بدون مجموعة (بما في ذلك الخاصة) يمكنك إعادة توجيهها إلى @FereyTONestBot</blockquote>",
}
