l_help_handler = {
    "ru": "<blockquote>👩🏽‍💻 <b>Команды</b> пользователя:\n\n/report - сообщить о нарушении\n/happy - получить радость\n/thanks - поблагодарить\n/birthday - поздравить\n/vote - голосовать\n\n👩🏽‍💻 <b>Добавь</b> <i>кѻмментарий</i> после команды если необходимо</blockquote>",
    "en": "<blockquote>👩🏽‍💻 <b>User</b> commands:\n\n/report - report a violation\n/happy - receive joy\n/thanks - thank\n/birthday - congratulate\n/vote - vote\n\n👩🏽‍💻 <b>Add</b> <i>comment</i> after the command if necessary</blockquote>",
    "es": "<blockquote>👩🏽‍💻 <b>Comandos</b> del usuario:\n\n/reportar - informar sobre una infracción\n/feliz - obtener alegría\n/gracias - agradecer\n/cumpleaños - felicitar\n/votar - votar\n\n👩🏽‍💻 <b>Agrega</b> <i>un comentario</i> después del comando si es necesario</blockquote>",
    "fr": "<blockquote>👩🏽‍💻 <b>Commandes</b> de l'utilisateur :\n\n/report - signaler une violation\n/happy - obtenir de la joie\n/thanks - remercier\n/birthday - féliciter\n/vote - voter\n\n👩🏽‍💻 <b>Ajoutez</b> <i>un commentaire</i> après la commande si nécessaire</blockquote>",
    "zh": "<blockquote>👩🏽‍💻 <b>用户</b>的命令：\n\n/report - 举报违规\n/happy - 获得快乐\n/thanks - 表达感谢\n/birthday - 祝贺\n/vote - 投票\n\n👩🏽‍💻 <b>如果需要</b>，在命令后添加 <i>评论</i></blockquote>",
    "ar": "<blockquote>👩🏽‍💻 <b>أوامر</b> المستخدم:\n\n/report - الإبلاغ عن انتهاك\n/happy - الحصول على السعادة\n/thanks - شكر\n/birthday - تهنئة\n/vote - التصويت\n\n👩🏽‍💻 <b>أضف</b> <i>تعليقًا</i> بعد الأمر إذا لزم الأمر</blockquote>",
}
