l_codex_caption_5 = {
    "ru": "👩🏽‍💻 <b>Акт #5</b>: <code>заключение</code>\n\n00:05 - результаты\n00:10 - вывод\n\n<blockquote><b>Рассмотрены</b> <u>@tg</u>-приложения #нейро-генерации/администрирования/поиска/блокчейн интеграции</blockquote>\n\n<tg-emoji emoji-id='5449885771420934013'>🌱</tg-emoji> <b>Переходи</b> к <a href='{0}'>реалити-фесту</a>, чтобы подробно в режиме <b>реального времени</b> собрать все @tg-инструменты для развития своего продукта\n\n🍃 <b>Становись</b> резидентом <a href='{1}'>закрытого канала</a>, чтобы приобрести <b>рабочую книгу</b> с актуальными знаниями и в числе первых получать инструкции нового @tg-функционала",
    "en": "👩🏽‍💻 <b>Act #5</b>: <code>conclusion</code>\n\n00:05 - results\n00:10 - summary\n\n<blockquote><b>Reviewed</b> <u>@tg</u>-applications #neuro-generation/administration/search/blockchain integration</blockquote>\n\n<tg-emoji emoji-id='5449885771420934013'>🌱</tg-emoji> <b>Join</b> the <a href='{0}'>reality fest</a> to collect in detail, in <b>real time</b>, all @tg-tools for developing your product\n\n🍃 <b>Become</b> a resident of the <a href='{1}'>closed channel</a> to get a <b>workbook</b> with up-to-date knowledge and be among the first to receive instructions on new @tg features",
    "es": "👩🏽‍💻 <b>Acto #5</b>: <code>conclusión</code>\n\n00:05 - resultados\n00:10 - resumen\n\n<blockquote><b>Revisadas</b> aplicaciones <u>@tg</u> #neuro-generación/administración/búsqueda/integración blockchain</blockquote>\n\n<tg-emoji emoji-id='5449885771420934013'>🌱</tg-emoji> <b>Pasa</b> al <a href='{0}'>festival de realidad</a> para recopilar en detalle, en <b>tiempo real</b>, todas las herramientas @tg para desarrollar tu producto\n\n🍃 <b>Conviértete</b> en residente del <a href='{1}'>canal cerrado</a> para obtener un <b>cuaderno de trabajo</b> con conocimientos actualizados y ser de los primeros en recibir instrucciones sobre las nuevas funciones de @tg",
    "fr": "👩🏽‍💻 <b>Acte #5</b>: <code>conclusion</code>\n\n00:05 - résultats\n00:10 - synthèse\n\n<blockquote><b>Examinées</b> applications <u>@tg</u> #neuro-génération/administration/recherche/intégration blockchain</blockquote>\n\n<tg-emoji emoji-id='5449885771420934013'>🌱</tg-emoji> <b>Rejoins</b> le <a href='{0}'>festival de la réalité</a> pour rassembler en détail, en <b>temps réel</b>, tous les outils @tg pour développer ton produit\n\n🍃 <b>Deviens</b> résident du <a href='{1}'>canal privé</a> pour obtenir un <b>carnet de travail</b> avec des connaissances à jour et être parmi les premiers à recevoir les instructions sur les nouvelles fonctionnalités @tg",
    "zh": "👩🏽‍💻 <b>行动 #5</b>: <code>结论</code>\n\n00:05 - 结果\n00:10 - 总结\n\n<blockquote><b>已审阅</b> <u>@tg</u> 应用 #神经生成/管理/搜索/区块链 集成</blockquote>\n\n<tg-emoji emoji-id='5449885771420934013'>🌱</tg-emoji> <b>前往</b> <a href='{0}'>现实节</a>，以在<b>实时</b>中详细收集所有用于发展您产品的 @tg 工具\n\n🍃 <b>成为</b> <a href='{1}'>封闭频道</a> 的成员，以获取一本包含最新知识的 <b>工作手册</b>，并成为第一批收到新 @tg 功能说明的人",
    "ar": "👩🏽‍💻 <b>الحدث #5</b>: <code>الاستنتاج</code>\n\n00:05 - النتائج\n00:10 - الخلاصة\n\n<blockquote><b>تمت مراجعة</b> تطبيقات <u>@tg</u> #التوليد_العصبي/الإدارة/البحث/تكامل_البلوكشين</blockquote>\n\n<tg-emoji emoji-id='5449885771420934013'>🌱</tg-emoji> <b>انتقل</b> إلى <a href='{0}'>مهرجان الواقع</a> لجمع جميع أدوات @tg لتطوير منتجك بالتفصيل وفي <b>الوقت الحقيقي</b>\n\n🍃 <b>كن</b> مقيمًا في <a href='{1}'>القناة المغلقة</a> للحصول على <b>كتاب عمل</b> بالمعرفة المحدثة ولكي تكون من أوائل من يتلقون تعليمات الوظائف الجديدة لـ @tg",
}
